if ~exist('src200sym','var')
    src200sym = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei200_align_sym3.sqw');
end
hc = hor_config;
ll = hc.log_level;
hc.log_level = -2;

w2_000a = cut(src200sym,line_proj('offset',[0,0,1]),[-0.1,0.1],0.04,0.04,[95,105]);
plot(w2_000a);lz 0 1;keep_figure; %[output:589a94c8]
w2_000b = cut(src200sym,line_proj('offset',[0,0,1]),[-0.1,0.1],0.04,0.04,[45,55]);
plot(w2_000b);lz 0 1; keep_figure; %[output:0f987681]


data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits\' %[output:176721b0]
fit_cuts_file = 'multicuts_fit_dataNG_ei200meV.mat' %[output:5bbeb5b3]
cuts_res_file = fullfile(data_path,fit_cuts_file);
if ~exist('cuts2fit200NG','var')
    cuts2fit200NG = recover_cuts_2fit(cuts_res_file,'cuts2fit200NG');
end

hc.log_level = ll;

othrEi200cut110 = {[-0.1,0.1],[-0.1,0.1],[0,2,160]};
file = src200sym.full_filename %[output:8529ac3a]
[~,fname] = fileparts(file);
%%
hc.log_level = -2;
e0=150;
w2_001 = cut(src200sym,line_proj('offset',[0,0,0]),0.04,0.04,[-0.1,0.1],[e0-10,e0+10]);
plot(w2_001);lz 0 0.4; liny; keep_figure; %[output:94787377]

w2_00 = cut(src200sym,line_proj(),0.04,0.04,[-0.1,0.1],[95,105]);
plot(w2_00);lz 0 1; %[output:2e644df8]
keep_figure; %[output:2e644df8]

hc.log_level = ll;
other_ranges200 = {[-0.1,0.1],[-0.1,0.1],[0,2,180]} %[output:92b53966]
%%
% <110> and up to two <200> min FF change cuts
lp110of200 = line_proj([-1,1,0],[1,1,0],'offset',[1,1,0]) %[output:46f89228]
w2_200NG = cut(src200sym,lp110of200,[-1,0.02,1],othrEi200cut110{:});
plot(w2_200NG);lz 0 1; keep_figure %[output:44b326c9]

fh = plot(w2_200NG); liny; lz 0 4; %[output:99b307b0]
[w2_200NGfit,cuts2fit200NG] = draw_masks_helper(fh, ...
    cuts2fit200NG, 'msk110_dirM110',3);
plot(w2_200NGfit); lz 0 1; keep_figure; %[output:99b307b0]

cuts2fit200NG.all_cff_cuts = w2_200NG;
%%
save(cuts_res_file,'cuts2fit200NG','-v7.3');
%%
scuts_path = 'e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts';
allJfitfile = fullfile(scuts_path,'NG_FFCutsFits.mat');
if ~exist('NG_FFCutsFits','var')
    NG_FFCutsFits = [];
end
w2_200NGfits = cut(w2_200NGfit,[0,0.005,0.35],[10,2,115],SymopReflection('normvec',[-1,1,0],'offset',[1,1,0]));
plot(w2_200NGfits);lz 0 1; keep_figure; %[output:64a99743]

NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ...
    'Ei200_off110NGminFF',w2_200NGfits);

%%
% specialized <200> cut with min FF change
lpm110of200 = line_proj([-1,1,0],[1,1,0],'offset',[2,0,0]);
w2_200NGOff200 = cut(w2_200NGfit,lpm110of200,[0,0.005,0.4],[],[],[10,2,135],SymopReflection('normvec',[1,-1,0],'offset',[1,1,0]));
plot(w2_200NGOff200);lz 0 1; %[output:60d5bbaa]

NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ...
    'Ei200_off200NGminFF',w2_200NGOff200);
%%
% <110> cut with max FF change
lp110of110 = line_proj([1,1,0],[1,-1,0],'offset',[1,1,0]);
w2_200NGoff110maxFF = cut(src200sym,lp110of110,[-1,0.02,3],othrEi200cut110{:});
fh = plot(w2_200NGoff110maxFF); liny; lz 0 1; %[output:0f4cd36d]
[w2_200NGoff110maxFF,cuts2fit200NG] = draw_masks_helper(fh, ...
    cuts2fit200NG, 'msk110_dir110',3);
plot(w2_200NGoff110maxFF); lz 0 1; keep_figure; %[output:0f4cd36d]

%%
NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ...
    'Ei200_off110NGmaxFF',cut(w2_200NGoff110maxFF,[0,0.02,0.4],[10,2,125]));
%%
% <200> cut with max FF change
lp110of200 = line_proj([1,1,0],[1,-1,0],'offset',[2,0,0]);
w2_200NGoff200maxFF = cut(src200sym,lp110of200,[-1,0.02,3],othrEi200cut110{:});
fh = plot(w2_200NGoff200maxFF); liny; lz 0 1; %[output:8aa4356a]
[w2_200NGoff200maxFF,cuts2fit200NG] = draw_masks_helper(fh, ...
    cuts2fit200NG, 'msk200_dir110',3);
plot(w2_200NGoff200maxFF); lz 0 1; keep_figure; %[output:8aa4356a]

lp110of020 = line_proj([1,1,0],[1,-1,0],'offset',[0,2,0]);
w2_200NGoff020maxFF = cut(src200sym,lp110of020,[-1,0.02,3],othrEi200cut110{:});
fh = plot(w2_200NGoff020maxFF); liny; lz 0 1; %[output:6832156b]
[w2_200NGoff020maxFF,cuts2fit200NG] = draw_masks_helper(fh, ...
    cuts2fit200NG, 'msk020_dir110',3);
plot(w2_200NGoff020maxFF); lz 0 1; keep_figure; %[output:6832156b]

w2ei200NGoff200maxFF = sqw_op_bin_pixels({w2_200NGoff200maxFF,w2_200NGoff020maxFF}, ...
    @move_all_to_proj, ...
    {[lp110of200,lp110of020]}, ...
    lp110of200,[0,0.01,0.5],othrEi200cut110{:},'-combine');
plot(w2ei200NGoff200maxFF);liny; lz 0 1;keep_figure; %[output:6766bba1]
%%
NG_FFCutsFits = save_selected_cuts(NG_FFCutsFits,allJfitfile, ...
    'Ei200_off200NGmaxFF',w2ei200NGoff200maxFF);
%%
save(cuts_res_file,'cuts2fit200NG','-v7.3');
%%
if ~exist('mi','var')
    mi = MagneticIons();
end
w2nbgc = mi.correct_mag_ff(w2nbg);
plot(w2nbgc); lz 0 1;keep_figure;
%%
 w2s1 = symmetrise_sqw(w2nbgc,SymopReflection('norm',[-1,1,0],'offset',[0,0,0]))
 plot(w2s1); lz 0 1;keep_figure;
%%
w2s1 = cut(w2s1,[0,0.01,2],[]);
w2s2 = symmetrise_sqw(w2s1,SymopReflection('norm',[1,-1,0],'offset',[0,2,0]))
plot(w2s2); lz 0 1;keep_figure;
%%
w2s3 = symmetrise_sqw(w2s2,SymopReflection('norm',[-1,1,0],'offset',[0.5,1.5,0]))
w2s3.data.axes.title = "Ei800, one dir; bg removed; ff corrected"
plot(w2s3); lz 0 1;keep_figure;

